/**
 * Aura Layout System
 *
 * This file contains the canonical layout and grid definitions for the Aura design system.
 * It exports structured data for LLM consumption, including breakpoints, grid configurations,
 * and container query patterns.
 *
 * Key Concepts:
 * - **Container Queries**: Layouts respond to their container's width, not the viewport
 * - **CSS Grid**: 12-column grid system with responsive breakpoints
 * - **Mobile-first**: Base styles apply to smallest screens, breakpoints add styles as width increases
 *
 * Usage:
 * 1. Wrap content in a container query context: `@container`
 * 2. Apply responsive grid classes: `grid grid-cols-4 @sm:grid-cols-8 @md:grid-cols-12`
 * 3. Use column spanning: `col-span-4 @md:col-span-6`
 */

// =============================================================================
// Breakpoint Definitions
// =============================================================================

export interface LayoutBreakpoint {
  name: string;
  min: number;
  max: number | null;
  columns: number;
  gutter: number;
  margin: number;
  prefix: string;
  description: string;
}

/**
 * Layout breakpoints for the Aura design system.
 *
 * Uses Tailwind's standard container query breakpoints for consistency.
 * Mobile-first: base styles (no prefix) apply below 640px.
 *
 * | Breakpoint | Range         | Columns | Prefix |
 * |------------|---------------|---------|--------|
 * | base       | 0-639px       | 4       | (none) |
 * | sm         | 640-767px     | 8       | @sm:   |
 * | md         | 768-1023px    | 12      | @md:   |
 * | lg         | 1024-1280px   | 12      | @lg:   |
 * | xl         | 1281-1536px   | 12      | @xl:   |
 */
export const layoutBreakpoints: LayoutBreakpoint[] = [
  {
    name: 'base',
    min: 0,
    max: 639,
    columns: 4,
    gutter: 8,
    margin: 16,
    prefix: '',
    description: 'Mobile devices, narrow containers. No prefix needed.',
  },
  {
    name: 'sm',
    min: 640,
    max: 767,
    columns: 8,
    gutter: 8,
    margin: 16,
    prefix: '@sm:',
    description: 'Tablets, medium containers.',
  },
  {
    name: 'md',
    min: 768,
    max: 1023,
    columns: 12,
    gutter: 16,
    margin: 12,
    prefix: '@md:',
    description: 'Laptops, large containers.',
  },
  {
    name: 'lg',
    min: 1024,
    max: 1280,
    columns: 12,
    gutter: 16,
    margin: 16,
    prefix: '@lg:',
    description: 'Desktops, large containers.',
  },
  {
    name: 'xl',
    min: 1281,
    max: 1536,
    columns: 12,
    gutter: 16,
    margin: 16,
    prefix: '@xl:',
    description: 'Wide desktops, extra large containers.',
  },
];

// =============================================================================
// Grid Patterns
// =============================================================================

export const gridPatterns = {
  container: {
    name: 'Container Query Context',
    description: 'Establishes a containment context for container queries',
    class: '@container',
    usage: 'Wrap any element that should respond to its own width',
  },
  namedContainer: {
    name: 'Named Container',
    description: 'Container with a name for targeted queries',
    class: '@container/layout',
    usage: 'Use when you need to target a specific container',
  },
  responsiveGrid: {
    name: 'Responsive Grid',
    description: 'Full responsive grid that adapts across all breakpoints',
    class:
      'grid grid-cols-4 gap-2 px-4 @sm:grid-cols-8 @md:grid-cols-12 @md:gap-4 @md:px-3',
    usage: 'Main content grid that adapts from 4 to 8 to 12 columns',
  },
  simpleGrid: {
    name: 'Simple 12-Column Grid',
    description: 'Fixed 12-column grid without responsive breakpoints',
    class: 'grid grid-cols-12 gap-4',
    usage: 'When container width is known to be large enough',
  },
} as const;

// =============================================================================
// Column Span Patterns
// =============================================================================

export interface ColumnSpan {
  name: string;
  fraction: string;
  base: string;
  sm: string;
  md: string;
  description: string;
}

export const columnSpans: ColumnSpan[] = [
  {
    name: 'Full Width',
    fraction: '12/12',
    base: 'col-span-4',
    sm: 'col-span-8',
    md: 'col-span-12',
    description: 'Spans entire width at all breakpoints',
  },
  {
    name: 'Three Quarters',
    fraction: '9/12',
    base: 'col-span-3',
    sm: 'col-span-6',
    md: 'col-span-9',
    description: 'Main content area in sidebar layouts',
  },
  {
    name: 'Two Thirds',
    fraction: '8/12',
    base: 'col-span-4',
    sm: 'col-span-5',
    md: 'col-span-8',
    description: 'Primary content with secondary sidebar',
  },
  {
    name: 'Half',
    fraction: '6/12',
    base: 'col-span-4',
    sm: 'col-span-4',
    md: 'col-span-6',
    description: 'Equal two-column layout',
  },
  {
    name: 'One Third',
    fraction: '4/12',
    base: 'col-span-4',
    sm: 'col-span-3',
    md: 'col-span-4',
    description: 'Three-column layout items',
  },
  {
    name: 'One Quarter',
    fraction: '3/12',
    base: 'col-span-2',
    sm: 'col-span-2',
    md: 'col-span-3',
    description: 'Four-column layout items, sidebars',
  },
  {
    name: 'One Sixth',
    fraction: '2/12',
    base: 'col-span-2',
    sm: 'col-span-2',
    md: 'col-span-2',
    description: 'Six-column layout items, narrow elements',
  },
];

// =============================================================================
// Layout Composition Patterns
// =============================================================================

export const layoutCompositions = {
  sidebarLeft: {
    name: 'Sidebar Left',
    description: 'Fixed sidebar on left, flexible main content',
    sidebar: 'col-span-4 @sm:col-span-2 @md:col-span-3',
    main: 'col-span-4 @sm:col-span-6 @md:col-span-9',
    usage: 'Navigation panels, settings pages',
  },
  sidebarRight: {
    name: 'Sidebar Right',
    description: 'Flexible main content, fixed sidebar on right',
    main: 'col-span-4 @sm:col-span-6 @md:col-span-9',
    sidebar: 'col-span-4 @sm:col-span-2 @md:col-span-3',
    usage: 'Detail panels, contextual information',
  },
  twoColumn: {
    name: 'Two Column',
    description: 'Equal width columns',
    column: 'col-span-4 @sm:col-span-4 @md:col-span-6',
    usage: 'Comparison views, side-by-side content',
  },
  threeColumn: {
    name: 'Three Column',
    description: 'Three equal columns, stacked on mobile',
    column: 'col-span-4 @sm:col-span-4 @md:col-span-4',
    usage: 'Card grids, feature lists',
  },
  fourColumn: {
    name: 'Four Column',
    description: 'Four equal columns, two on tablet, stacked on mobile',
    column: 'col-span-4 @sm:col-span-4 @md:col-span-3',
    usage: 'Metric dashboards, icon grids',
  },
  contentCentered: {
    name: 'Centered Content',
    description: 'Narrow centered content with gutters',
    container:
      'col-span-4 @sm:col-span-6 @sm:col-start-2 @md:col-span-8 @md:col-start-3',
    usage: 'Article content, forms, focused reading',
  },
} as const;

// =============================================================================
// Utility Functions
// =============================================================================

/**
 * Get breakpoint by name
 */
export function getBreakpoint(name: string): LayoutBreakpoint | undefined {
  return layoutBreakpoints.find((bp) => bp.name === name);
}

/**
 * Get container query prefix for a breakpoint
 */
export function getContainerPrefix(breakpoint: string): string {
  const bp = layoutBreakpoints.find((b) => b.name === breakpoint);
  return bp?.prefix ?? '';
}

/**
 * Generate responsive column span classes
 */
export function getResponsiveSpan(
  base: number,
  sm: number,
  md: number
): string {
  return `col-span-${base} @sm:col-span-${sm} @md:col-span-${md}`;
}

// =============================================================================
// Code Examples for LLM Consumption
// =============================================================================

export const layoutExamples = {
  basicGrid: `
<!-- Basic responsive grid -->
<div class="@container">
  <div class="grid grid-cols-4 gap-2 @sm:grid-cols-8 @md:grid-cols-12 @md:gap-4">
    <div class="col-span-4 @md:col-span-12">Full width header</div>
    <div class="col-span-4 @sm:col-span-6 @md:col-span-9">Main content</div>
    <div class="col-span-4 @sm:col-span-2 @md:col-span-3">Sidebar</div>
  </div>
</div>`,

  sidebarLayout: `
<!-- Sidebar layout with container queries -->
<div class="@container">
  <div class="grid grid-cols-4 gap-2 @sm:grid-cols-8 @md:grid-cols-12 @md:gap-4">
    <!-- Sidebar: 4 cols on mobile, 2 on sm, 3 on md+ -->
    <aside class="col-span-4 @sm:col-span-2 @md:col-span-3 bg-muted p-4 rounded-lg">
      <nav>Navigation</nav>
    </aside>

    <!-- Main: 4 cols on mobile, 6 on sm, 9 on md+ -->
    <main class="col-span-4 @sm:col-span-6 @md:col-span-9">
      <article>Main content</article>
    </main>
  </div>
</div>`,

  cardGrid: `
<!-- Three-column card grid -->
<div class="@container">
  <div class="grid grid-cols-4 gap-4 @sm:grid-cols-8 @md:grid-cols-12">
    <!-- Cards stack on mobile, 2 cols on sm, 3 cols on md+ -->
    <div class="col-span-4 @sm:col-span-4 @md:col-span-4 bg-card p-4 rounded-lg border">
      Card 1
    </div>
    <div class="col-span-4 @sm:col-span-4 @md:col-span-4 bg-card p-4 rounded-lg border">
      Card 2
    </div>
    <div class="col-span-4 @sm:col-span-4 @md:col-span-4 bg-card p-4 rounded-lg border">
      Card 3
    </div>
  </div>
</div>`,

  centeredContent: `
<!-- Centered narrow content -->
<div class="@container">
  <div class="grid grid-cols-4 gap-4 @sm:grid-cols-8 @md:grid-cols-12">
    <article class="col-span-4 @sm:col-span-6 @sm:col-start-2 @md:col-span-8 @md:col-start-3">
      <h1 class="text-3xl font-bold mb-4">Article Title</h1>
      <p class="text-base text-muted-foreground">
        Centered content that maintains readable line lengths.
      </p>
    </article>
  </div>
</div>`,

  nestedContainers: `
<!-- Nested container queries -->
<div class="@container/page">
  <div class="grid grid-cols-12 gap-4">
    <main class="col-span-9 @container/main">
      <!-- This grid responds to main's width, not the page -->
      <div class="grid grid-cols-1 @[400px]/main:grid-cols-2 @[600px]/main:grid-cols-3 gap-4">
        <div>Item 1</div>
        <div>Item 2</div>
        <div>Item 3</div>
      </div>
    </main>
    <aside class="col-span-3">Sidebar</aside>
  </div>
</div>`,

  dashboardLayout: `
<!-- Dashboard with metrics and content -->
<div class="@container">
  <div class="grid grid-cols-4 gap-4 @sm:grid-cols-8 @md:grid-cols-12">
    <!-- Metrics row: 2 cols on mobile, spans adjust on larger containers -->
    <div class="col-span-2 @sm:col-span-2 @md:col-span-3 bg-card p-4 rounded-lg border">
      <p class="text-sm text-muted-foreground">Users</p>
      <p class="text-2xl font-bold">12,345</p>
    </div>
    <div class="col-span-2 @sm:col-span-2 @md:col-span-3 bg-card p-4 rounded-lg border">
      <p class="text-sm text-muted-foreground">Revenue</p>
      <p class="text-2xl font-bold">$45,678</p>
    </div>
    <div class="col-span-2 @sm:col-span-2 @md:col-span-3 bg-card p-4 rounded-lg border">
      <p class="text-sm text-muted-foreground">Orders</p>
      <p class="text-2xl font-bold">890</p>
    </div>
    <div class="col-span-2 @sm:col-span-2 @md:col-span-3 bg-card p-4 rounded-lg border">
      <p class="text-sm text-muted-foreground">Growth</p>
      <p class="text-2xl font-bold text-green-600">+12%</p>
    </div>

    <!-- Main chart area -->
    <div class="col-span-4 @sm:col-span-8 @md:col-span-12 bg-card p-4 rounded-lg border min-h-64">
      Chart placeholder
    </div>
  </div>
</div>`,
};

export type GridPattern = keyof typeof gridPatterns;
export type LayoutComposition = keyof typeof layoutCompositions;

@import url("https://fonts.googleapis.com/css2?family=Inter:wght@100..900&family=Space+Grotesk:wght@300..700&family=Source+Code+Pro:wght@200..900&display=swap");
@import "tailwindcss";
@import "tw-animate-css";
@import "./colors.css";

@custom-variant dark (&:is(.dark *));

/* Dark mode configuration */
@variant dark (@media (prefers-color-scheme: dark));
@variant dark (.dark &);

@theme inline {
  /* Container query breakpoint overrides for layout system */
  --container-2xl: 40rem; /* 640px - Override Tailwind's default 672px */
  --container-8xl: 96rem; /* 1536px - Custom breakpoint for widest layouts */

  /* Typography scale overrides - font sizes */
  --text-2xs: 0.625rem;
  --text-2xl: 1.5rem;
  --text-3xl: 1.75rem;
  --text-4xl: 2rem;
  --text-5xl: 2.25rem;

  /* Typography scale overrides - line heights */
  --text-2xs--line-height: 0.75rem;
  --text-xs--line-height: 0.875rem;
  --text-sm--line-height: 1.125rem;
  --text-base--line-height: 1.25rem;
  --text-lg--line-height: 1.5rem;
  --text-xl--line-height: 1.5rem;
  --text-2xl--line-height: 1.75rem;
  --text-3xl--line-height: 2rem;
  --text-4xl--line-height: 2.5rem;
  --text-5xl--line-height: 2.75rem;

  --font-sans: var(--font-inter);
  --font-marketing: var(--font-space-grotesk);
  --font-mono: var(--font-source-code-pro);
  --tracking-tight: -0.04px;
  --tracking-tighter: -0.08px;
  --tracking-tightest: -0.1px;
  --shadow-sm: 0 1px 2px 0 var(--effect-shadow-sm);
  --shadow-default:
    0 1px 3px 0 var(--effect-shadow-md), 0 1px 2px 0 var(--effect-shadow-sm);
  --shadow-md:
    0 4px 6px -1px var(--effect-shadow-md),
    0 2px 4px -1px var(--effect-shadow-sm);
  --shadow-lg:
    0 10px 15px -3px var(--effect-shadow-lg),
    0 4px 6px -2px var(--effect-shadow-sm);
  --shadow-xl:
    0 20px 25px -5px var(--effect-shadow-xl),
    0 10px 10px -5px var(--effect-shadow-lg);
  --shadow-focus-ring: 0 0 0 2px var(--ring), 0 0 0 4px var(--ring-muted);
  --shadow-focus-ring-destructive:
    0 0 0 2px var(--ring-critical), 0 0 0 4px var(--ring-critical-shadow);

  --radius-none: 0px;
  --radius-xs: 2px;
  --radius-sm: 4px;
  --radius-md: 6px;
  --radius-lg: 8px;
  --radius-xl: 12px;
  --radius-2xl: 16px;
  --radius-3xl: 24px;
  --radius-4xl: 32px;
  --radius-full: 9999px;
  --avatar-icon-default: 1.09375rem;
  --avatar-icon-xs: 0.875rem;
  --avatar-icon-xxs: 0.65625rem;
  --avatar-image-backdrop: rgba(2, 6, 23, 0.2);

  /* Legacy semantic utility aliases */
  --color-primary: var(--primary);
  --color-primary-hover: var(--primary-hover);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-hover: var(--secondary-hover);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --color-ring-shadow: var(--ring-shadow);
  --color-ring-destructive: var(--ring-destructive);
  --color-ring-destructive-shadow: var(--ring-destructive-shadow);
  --color-destructive: var(--destructive);
  --color-destructive-hover: var(--destructive-hover);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-warning: var(--warning);
  --color-warning-hover: var(--warning-hover);
  --color-warning-foreground: var(--warning-foreground);
  --color-success: var(--success);
  --color-success-hover: var(--success-hover);
  --color-success-foreground: var(--success-foreground);
  --color-neutral: var(--neutral);
  --color-neutral-hover: var(--neutral-hover);
  --color-neutral-foreground: var(--neutral-foreground);
  --color-undefined: var(--undefined);
  --color-undefined-hover: var(--undefined-hover);
  --color-undefined-foreground: var(--undefined-foreground);
  --color-disabled: var(--disabled);
  --color-disabled-foreground: var(--disabled-foreground);
  --color-hover: var(--hover);
  --color-foreground-link: var(--foreground-link);
  --color-backdrop: var(--backdrop);
  --color-toggled: var(--toggled);
  --color-toggled-hover: var(--toggled-hover);
  --color-toggled-foreground: var(--toggled-foreground);
  --color-sidebar: var(--sidebar);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-ring: var(--sidebar-ring);

  /* Additional legacy decorative aliases */
  --color-decorative-background-mountain: var(--decorative-background-mountain);
  --color-decorative-background-fjord: var(--decorative-background-fjord);
  --color-decorative-background-nordic: var(--decorative-background-nordic);
  --color-decorative-background-aurora: var(--decorative-background-aurora);
  --color-decorative-background-dusk: var(--decorative-background-dusk);
  --color-decorative-background-orange: var(--decorative-background-orange);
  --color-decorative-background-sky: var(--decorative-background-sky);
  --color-decorative-background-gray: var(--decorative-background-gray);
  --color-decorative-background-hover-mountain: var(--decorative-background-hover-mountain);
  --color-decorative-background-hover-fjord: var(--decorative-background-hover-fjord);
  --color-decorative-background-hover-nordic: var(--decorative-background-hover-nordic);
  --color-decorative-background-hover-aurora: var(--decorative-background-hover-aurora);
  --color-decorative-background-hover-dusk: var(--decorative-background-hover-dusk);
  --color-decorative-background-hover-orange: var(--decorative-background-hover-orange);
  --color-decorative-background-hover-sky: var(--decorative-background-hover-sky);
  --color-decorative-background-hover-gray: var(--decorative-background-hover-gray);
  --color-decorative-foreground-mountain: var(--decorative-foreground-mountain);
  --color-decorative-foreground-fjord: var(--decorative-foreground-fjord);
  --color-decorative-foreground-nordic: var(--decorative-foreground-nordic);
  --color-decorative-foreground-aurora: var(--decorative-foreground-aurora);
  --color-decorative-foreground-dusk: var(--decorative-foreground-dusk);
  --color-decorative-foreground-orange: var(--decorative-foreground-orange);
  --color-decorative-foreground-sky: var(--decorative-foreground-sky);
  --color-decorative-foreground-gray: var(--decorative-foreground-gray);

  --color-gradient-nordic: var(--gradient-nordic);
  --color-gradient-aurora: var(--gradient-aurora);
  --color-gradient-dusk: var(--gradient-dusk);
  --color-gradient-equinox: var(--gradient-equinox);
  --color-gradient-summer: var(--gradient-summer);
  --color-gradient-spring: var(--gradient-spring);
  --color-gradient-fall: var(--gradient-fall);

  --color-fjord: var(--fjord-50);
  --color-nordic: var(--nordic-50);
  --color-aurora: var(--aurora-50);
  --color-sky: var(--sky-50);
}

:root {
  --radius: 0.375rem;
  --font-inter: "Inter", sans-serif;
  --font-space-grotesk: "Space Grotesk", sans-serif;
  --font-source-code-pro: "Source Code Pro", monospace;
  --code-block-collapsed-height: 6.5rem;
  --code-block-fade-height: 0.9375rem;
  --message-content-max-width: 80%;
  --alert-icon-width: calc(var(--spacing) * 4);
  --drawer-max-height: 80vh;

  --gradient-nordic: linear-gradient(
    -100deg,
    var(--nordic-50) 0%,
    var(--nordic-400) 44%,
    var(--nordic-200) 100%
  );
  --gradient-aurora: linear-gradient(
    -100deg,
    var(--aurora-50) 0%,
    var(--aurora-400) 50%,
    var(--aurora-200) 100%
  );
  --gradient-dusk: linear-gradient(
    -100deg,
    var(--dusk-50) 0%,
    var(--dusk-400) 48%,
    var(--dusk-200) 100%
  );
  --gradient-equinox: linear-gradient(
    -100deg,
    var(--dusk-600) 0%,
    var(--dusk-300) 40%,
    var(--aurora-50) 60%,
    var(--aurora-100) 100%
  );
  --gradient-summer: linear-gradient(
    -100deg,
    var(--nordic-100) 0%,
    var(--dusk-50) 50%,
    var(--aurora-100) 100%
  );
  --gradient-spring: linear-gradient(
    -100deg,
    var(--aurora-50) 0%,
    var(--nordic-100) 50%,
    var(--aurora-100) 100%
  );
  --gradient-fall: linear-gradient(
    -100deg,
    var(--fjord-550) 0%,
    var(--dusk-550) 50%,
    var(--dusk-300) 100%
  );

  /* Legacy semantic aliases mapped to latest token model */
  --card: var(--card-background);
  --card-foreground: var(--foreground);
  --popover: var(--popover-background);
  --popover-foreground: var(--foreground);
  --primary: var(--primary-background);
  --primary-hover: var(--primary-background-hover);
  --primary-foreground: var(--foreground-on-primary);
  --secondary: var(--secondary-background);
  --secondary-hover: var(--secondary-background-hover);
  --muted: var(--muted-background);
  --accent: var(--active-muted-background);
  --accent-foreground: var(--active-foreground);
  --mountain: var(--muted-background);
  --mountain-foreground: var(--foreground);
  --foreground-link: var(--link-foreground);
  --input: var(--border);
  --ring-shadow: var(--ring-muted);
  --ring-destructive: var(--ring-critical);
  --ring-destructive-shadow: var(--ring-critical-shadow);
  --backdrop: var(--overlay-background);
  --destructive: var(--destructive-background);
  --destructive-hover: var(--destructive-background-hover);
  --warning: var(--warning-background);
  --warning-hover: var(--warning-background-hover);
  --success: var(--success-background);
  --success-hover: var(--success-background-hover);
  --neutral: var(--neutral-background);
  --neutral-hover: var(--neutral-background-hover);
  --undefined: var(--neutral-muted-background);
  --undefined-hover: var(--neutral-background-hover);
  --undefined-foreground: var(--neutral-foreground);
  --disabled: var(--disabled-background);
  --hover: var(--background-hover);
  --destructive-foreground-alternate: var(--destructive-foreground-on-critical);
  --destructive-alternative: var(--destructive-muted-background);
